      pt: ["Área de cerca de 44,8 quilómetros quadrados.", "Profundidade máxima de 33,3 metros.", "Localizado na parte nordeste do país.", "Parte do lago pertence à Bielorrússia."],
      fr: ["Superficie d'environ 44,8 kilomètres carrés.", "Profondeur maximale de 33,3 mètres.", "Situé dans la partie nord-est du pays.", "Une partie du lac appartient à la Biélorussie."],
