    type: "lake",
    name: { de: "Tauragnas-See", hu: "Tauragnas-tó", ro: "Lacul Tauragnas", en: "Lake Tauragnas"},
    image: "/poi-images/lithuania-tauragnas-lake-nature-v2.webp",
