      es: ["La longitud de los bucles supera los 60 kilómetros medidos a lo largo del río.", "La torre de observación de Birštonas tiene 45 metros de altura, una de las más altas de Lituania.", "El castro de Punia se alza en una de las penínsulas del bucle del río.", "Se han documentado más de 1000 especies de plantas en el territorio del parque.", "La región ya era una importante línea de defensa contra los caballeros teutónicos en el siglo XIV.", "El centro de visitantes del parque presenta modelos geológicos detallados."],
      pt: ["O comprimento dos loops excede 60 quilómetros medidos ao longo do rio.", "A torre de observação de Birštonas tem 45 metros de altura, uma das mais altas da Lituânia.", "O castro de Punia ergue-se numa das penínsulas da curva do rio.", "Mais de 1000 espécies de plantas foram documentadas na área do parque.", "A região já era uma importante linha de defesa contra os cavaleiros teutónicos no século XIV.", "O centro de visitantes do parque apresenta modelos geológicos detalhados."],
      fr: ["La longueur des boucles dépasse 60 kilomètres mesurés le long du fleuve.", "La tour d'observation de Birštonas mesure 45 mètres de haut, l'une des plus hautes de Lituanie.", "Le fort de Punia s'élève sur l'une des péninsules de la boucle du fleuve.", "Plus de 1000 espèces de plantes ont été documentées sur le territoire du parc.", "La région était déjà une ligne de défense importante contre les chevaliers teutoniques au XIVe siècle.", "Le centre de visiteurs du parc présente des modèles géologiques détaillés."],
